import pandas as pd

def most_common_sizes(sizes):
    """Return the most common size(s) of a Categorical of shirt sizes, as a list."""
    mode_result = sizes.mode()
    if not isinstance(mode_result, pd.Series) or len(mode_result) == 0:
        return []
    return mode_result.tolist()
```

