import numpy as np

def scalar_type_of(spec):
    """Return the NumPy scalar type for a dtype given as a string, a type or a dtype."""
    if isinstance(spec, str):
        spec = np.dtype(spec)
    elif not isinstance(spec, np.dtype):
        spec = np.array([spec]).dtype
    return spec.type
