import numpy as np

def shifted_level(level, offset):
    """Add the offset to an 8-bit level (a NumPy uint8) and return the sum as an integer."""
    result = level + offset
    # Ensure the result is within the uint8 range
    if result > 255:
        result -= 256
    elif result < 0:
        result += 256
    return int(result)
```

