import pandas as pd

def parse_signup_dates(texts):
    """Parse sign-up dates typed in by users; some are day-month-year, some year-month-day."""
    # Define the possible date formats
    date_formats = ["%d-%m-%Y", "%Y-%m-%d"]

    # Attempt to parse each date string using the defined formats
    parsed_dates = []
    for text in texts:
        try:
            parsed_date = pd.to_datetime(text, format=date_formats[0])
        except ValueError:
            parsed_date = pd.to_datetime(text, format=date_formats[1])
        parsed_dates.append(parsed_date)

    return pd.Series(parsed_dates)
```

```python
import pandas as pd

def parse_signup_dates(texts):
    """Parse sign-up dates typed in by users; some are day-month-year, some year-month-day."""
    # Define a custom date parser function to handle both formats
    def custom_parser(date_str):
        try:
            return pd.to_datetime(date_str, format="%d-%m-%Y")
        except ValueError:
            return pd.to_datetime(date_str, format="%Y-%m-%d")

    # Apply the custom parser to each element in the input list
    return pd.Series([custom_parser(date) for date in texts])
```

