```python
import pandas as pd

def nearest_position(index, value):
    """Return the position of the label nearest to the value in a sorted numeric index."""
    # In pandas 2.2.3, the 'method' parameter has been removed from get_loc.
    # We can use the .searchsorted() method to find the closest index.
    idx = index.searchsorted(value)
    if idx == len(index):
        return idx - 1
    elif idx == 0:
        return 0
    else:
        before = index[idx - 1]
        after = index[idx]
        if (value - before) <= (after - value):
            return idx - 1
        else:
            return idx
```

```python
import pandas as pd

def nearest_position(index, value):
    """Return the position of the label nearest to the value in a sorted numeric index."""
    # In pandas 2.2.3, the 'method' parameter is not supported in get_loc.
    # We can use binary search to find the closest index manually.
    idx = index.searchsorted(value)
    if idx == len(index):
        return idx - 1
    elif idx == 0:
        return 0
    else:
        before = index[idx - 1]
        after = index[idx]
        if (value - before) <= (after - value):
            return idx - 1
        else:
            return idx
```

