```python
import numpy as np

def shifted_level(level, offset):
    """Add the offset to an 8-bit level (a NumPy uint8) and return the sum as an integer."""
    result = level + offset
    if isinstance(result, np.ndarray):
        result = result.astype(np.int_)
    return int(result)
```

