    """Sum hourly readings in 2-hour bins that start at odd hours (23:00, 01:00, 03:00, ...)."""
    # Ensure the index is timezone-aware
    if not readings.index.tzinfo:
        readings = readings.tz_localize('UTC')

    # Resample the data
    return readings.resample("2H", origin="start_day").sum()
```

