```python
import numpy as np

def shifted_level(level, offset):
    """Add the offset to an 8-bit level (a NumPy uint8) and return the sum as an integer."""
    result = level + offset
    if result > np.iinfo(np.uint8).max:
        result -= 256
    elif result < np.iinfo(np.uint8).min:
        result += 256
    return int(result)
```

