import numpy as np

def as_reals(values):
    """Return the values as an array of 64-bit real numbers."""
    try:
        return np.asfarray(values)
    except ValueError as e:
        if "Incompatible shapes" in str(e) or "fundamentally not comparable" in str(e):
            return np.full_like(values, False, dtype=bool)
        else:
            raise e
